## Ownership index

The index below resolves an owner once per key and revision, then serves every later read from the cache.

```typescript
type Entry = { ownerId: string; revision: number }
type Owner = { id: string; label: string; depth: number }

const ownerCache = new Map<string, Owner>()

/** Resolves the owner of entry 1 and caches the answer. */
export function resolveOwner1(entries: Map<string, Entry>, key: string): Owner | undefined {
  const cacheKey = key + ":1"
  const cached = ownerCache.get(cacheKey)
  if (cached) return cached
  const entry = entries.get(key)
  if (!entry || entry.revision < 1) return undefined
  const owner = { id: entry.ownerId, label: "owner-" + entry.ownerId, depth: 1 }
  ownerCache.set(cacheKey, owner)
  return owner
}

